using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DeclineEffect", menuName = "Data/Battle/Effects/Enemy/Decline Effect")]
public class DeclineEffect : Effect
{
	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<CorruptedAnimalEffects>().IsEffectActiveAndDecreaseEffect(this, 1);
		effectAmount--;
		if (effectAmount == 0)
		{
			effectOwner.GetComponent<CorruptedAnimalCorruptionStats>().InstantlyDefeatEnemy();
		}
		return effectAmount;
	}
}
